#include <stdio.h>

int compare(const char *a, const char *b) {
    int i = 0;
    while (a[i] != '\0' && a[i] == b[i]) {
        i++;
    }
    return a[i] - b[i];
}

int main() {
    printf("%d\n", compare("apple", "apple") == 0);
    printf("%d\n", compare("apple", "banana") < 0);
    printf("%d\n", compare("pear", "peach") > 0);
    return 0;
}
